def tree_to_mermaid_lines(tree: dict, max_depth: int = 4) -> list:
    """将树结构（name/children 嵌套格式）转为 Mermaid mindmap 行"""
    name = sanitize_mermaid(tree.get('name', '根节点'))
    if not name:
        name = '根节点'
    name = name[:60]
    root_line = f'root(({name}))'

    def render(node: dict, depth: int) -> list:
        text = sanitize_mermaid(node.get('name', '节点'))[:60]
        if not text:
            text = '节点'
        prefix = '  ' * depth
        line = f'{prefix}{text}'
        result = [line]
        if depth < max_depth:
            children = node.get('children', [])
            for child in children[:10]:  # 限制子节点数量，避免 Mermaid 渲染崩溃
                result.extend(render(child, depth + 1))
        return result

    lines = [root_line]
    for child in tree.get('children', [])[:10]:
        lines.extend(render(child, 1))
    return lines


def generate_mermaid_md(slug: str, mindmap_json_path: str, dest_dir: str, title: str = '') -> Optional[str]:
    """从 mindmap JSON 生成 Mermaid mindmap .md 文件，供 Obsidian 原生渲染

    支持两种格式自动检测：
    - Canvas 格式（nodes/edges 键）
    - 树结构格式（name/children 键）
    """
    try:
        with open(mindmap_json_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception:
        return None

    # 自动检测格式
    if 'nodes' in data or 'edges' in data:
        lines = canvas_to_mermaid_lines(data)
    elif 'name' in data:
        lines = tree_to_mermaid_lines(data)
    elif 'children' in data and not 'name' in data:
        # 直接是 children 数组（无根节点名）
        data_with_root = {'name': title or slug, 'children': data.get('children', [])}
        lines = tree_to_mermaid_lines(data_with_root)
    else:
        lines = []

    if not lines:
        return None

    content = f"""---
title: "{title or slug} 脑图"
type: mindmap
source: raw/notebooklm-mindmaps/{slug}.json
---

```mindmap
{chr(10).join(lines)}
```
"""
    dest_path = os.path.join(dest_dir, f'{slug}.md')
    with open(dest_path, 'w', encoding='utf-8') as f:
        f.write(content)
    return dest_path"}
